<script setup lang="ts">
import { computed, ref } from 'vue';import { entries } from '../stores/diary';import EntryThumbnail from '../components/EntryThumbnail.vue'
const mode=ref<'calendar'|'list'>('calendar'),month=ref(new Date());const title=computed(()=>new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'long'}).format(month.value));const monthEntries=computed(()=>entries.value.filter(e=>{const d=new Date(e.date+'T12:00');return d.getFullYear()===month.value.getFullYear()&&d.getMonth()===month.value.getMonth()}));const cells=computed(()=>{const y=month.value.getFullYear(),m=month.value.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();return [...Array(first).fill(null),...Array.from({length:days},(_,i)=>i+1)]});function move(n:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1)}function getEntry(day:number){return monthEntries.value.find(e=>Number(e.date.slice(-2))===day)}
</script>
<template><div class="page"><header class="page-header"><p class="eyebrow">YOUR MOMENTS</p><h1>記録</h1><p>書いた日も、休んだ日も。すべてあなたの歩幅です。</p></header><div class="segmented"><button :class="{active:mode==='calendar'}" @click="mode='calendar'">カレンダー</button><button :class="{active:mode==='list'}" @click="mode='list'">一覧</button></div>
<section v-if="mode==='calendar'" class="calendar-card"><div class="month-nav"><button @click="move(-1)">‹</button><h2>{{title}}</h2><button @click="move(1)">›</button></div><div class="week"><span v-for="w in ['日','月','火','水','木','金','土']">{{w}}</span></div><div class="days"><span v-for="(d,i) in cells" :key="i" :class="{written:d&&getEntry(d)}"><template v-if="d"><RouterLink v-if="getEntry(d)" :to="`/entry/${getEntry(d)!.id}`">{{d}}<i></i></RouterLink><b v-else>{{d}}</b></template></span></div><div class="calendar-note"><span>● 記録した日</span><span>{{monthEntries.length}}日、言葉を残しました</span></div></section>
<section v-else class="recent-list"><RouterLink v-for="e in entries" :key="e.id" :to="`/entry/${e.id}`" class="entry-row"><EntryThumbnail :id="e.thumbnailImageId"/><div class="entry-icon" v-if="!e.thumbnailImageId">{{['🌙','🌿','☀️','☁️','🍃'][e.mood-1]}}</div><div><small>{{new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium'}).format(new Date(e.date+'T12:00'))}}</small><h3>{{e.body}}</h3><p><span v-for="t in e.tags" :key="t">#{{t}} </span></p></div><b>›</b></RouterLink></section></div></template>
